package pt.qpetiscos.agenda;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;
public class WidgetSettings extends Activity {
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);} GradientDrawable panel(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String value,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 @Override public void onCreate(Bundle b){super.onCreate(b);int id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);setResult(RESULT_CANCELED);if(id<0){finish();return;}
 int white=Color.WHITE,brown=0xff402817;getWindow().setStatusBarColor(white);getWindow().setNavigationBarColor(white);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
 ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(white);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(20),dp(24),dp(20),dp(24));scroll.addView(l);if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);scroll.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return WindowInsets.CONSUMED;});}
 l.addView(text("Fundo do widget",24,brown,true));TextView desc=text("Escolhe o tema da Agenda QPetiscos.",14,0xff795e49,false);desc.setPadding(0,dp(6),0,dp(20));l.addView(desc);
 String[] names={"Branco","Castanho escuro","Castanho claro"};int[] backgrounds={white,brown,0xff966039},cards={0xfff4f0ea,0xff5a3d29,0xff80502e},colors={brown,white,white};for(int i=0;i<3;i++){final int theme=i;LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable outer=panel(backgrounds[i],14);outer.setStroke(dp(1),0xffd8c8ba);box.setBackground(outer);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);l.addView(box,lp);box.addView(text(names[i],16,colors[i],true));TextView sample=text("Reserva  •  12:30  •  4 pessoas",13,colors[i],false);sample.setBackground(panel(cards[i],10));sample.setPadding(dp(12),dp(10),dp(12),dp(10));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(10);box.addView(sample,sp);box.setContentDescription("Selecionar tema "+names[i]);box.setFocusable(true);box.setOnClickListener(v->{getSharedPreferences("widget_theme",0).edit().putInt("theme"+id,theme).apply();WidgetAgenda.refreshAll(this);WidgetAgenda.schedule(this);Intent result=new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);setResult(RESULT_OK,result);finish();});}setContentView(scroll);}
}